%[text] # Visually inspect plots from simulation with Road Grade Profile block
evalin("base", "setParams_HarnessModel_CustomRoadGradeProfile_4")

sim_out = sim(sim_in);
result = extractTimetable(sim_out.logsout);
varnames = [
"Grade percent"
"Incline angle"
"Curvilinear speed"
"Horizontal position"
"Elevation"
];
for k = 1 : numel(varnames) %[output:group:1f10e945]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=150); %[output:78550a30] %[output:018d03c1] %[output:188af010] %[output:79e9c6ff] %[output:288f1e62]
end  % for %[output:group:1f10e945]
